window.RP_SESSION={"id":"S-706846032c41","messages":[{"id":"RP-0016486","time":"2026-01-15T00:54:00+09:00","room":"RP","name":"유노","profile":"사무라이 여고생","identity":"reviewed","type":"dialogue","body":"... (마을을 멍하니 바라보고 있다.)","characters":["P-0a9529a818e0"]},{"id":"RP-0016487","time":"2026-01-15T01:03:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"풍경이 아름답지요?\"\n\n멍하니 마을을 바라보는 유노 옆에 슬쩍 나타난 엘프가 말을 걸어왔다.","characters":["P-5d0c306440d0"]},{"id":"RP-0016488","time":"2026-01-15T01:06:00+09:00","room":"RP","name":"유노","profile":"사무라이 여고생","identity":"reviewed","type":"dialogue","body":"\"어, •••네. 아름답네요.\"\n\n소리없이 다가온 그녀에 살짝 당황하였지만 무덤덤한 모습을 보인다.\n\n\"...엘프, 네요.\"","characters":["P-0a9529a818e0"]},{"id":"RP-0016489","time":"2026-01-15T01:07:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"엘프는 처음이에요?\"\n\n자연스럽게 유노 옆자리를 차지합니다.","characters":["P-5d0c306440d0"]},{"id":"RP-0016490","time":"2026-01-15T01:07:00+09:00","room":"RP","name":"유노","profile":"사무라이 여고생","identity":"reviewed","type":"dialogue","body":"\"네, 모든 게... 처음이에요.\"","characters":["P-0a9529a818e0"]},{"id":"RP-0016491","time":"2026-01-15T01:09:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"모든게 처음이라... 그럼 앞으로가 많이 기대되겠네요\"","characters":["P-5d0c306440d0"]},{"id":"RP-0016492","time":"2026-01-15T01:10:00+09:00","room":"RP","name":"유노","profile":"사무라이 여고생","identity":"reviewed","type":"dialogue","body":"\"...\"\n\n그녀의 말에 고개를 끄덕인다.\n...\n\n\"네, 기대되면서도... 조금은 걱정되네요...\"","characters":["P-0a9529a818e0"]},{"id":"RP-0016493","time":"2026-01-15T01:12:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"걱정이 앞서나요?\"\n\n\"너무 걱정하진 말아요. 물론 처음 하는 것에 실수는 있겠지만, 누구나 처음엔 실수를 하니깐요\"","characters":["P-5d0c306440d0"]},{"id":"RP-0016494","time":"2026-01-15T01:13:00+09:00","room":"RP","name":"유노","profile":"사무라이 여고생","identity":"reviewed","type":"dialogue","body":"\"...응, 그렇죠...\"\n\n폴라리스의 말에 공감한다.","characters":["P-0a9529a818e0"]},{"id":"RP-0016495","time":"2026-01-15T01:14:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"가장 먼저 해보고싶은건 있나요?\"","characters":["P-5d0c306440d0"]},{"id":"RP-0016496","time":"2026-01-15T02:17:00+09:00","room":"RP","name":"시스템","profile":"","identity":"system","type":"system","body":"사무라이 여고생님이 나갔습니다.","characters":[]},{"id":"RP-0016497","time":"2026-01-15T02:17:00+09:00","room":"RP","name":"폴라리스","profile":"루체","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-5d0c306440d0"]},{"id":"RP-0016498","time":"2026-01-15T02:17:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]}]};
